package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Integer;
    attribute brightness : Real := 0.0;
    perform action tick {
      first start;
      then assign brightness := (if ((brightness) >= (255.0)) ? 0.0 else brightness + (io_1 * 255.0 / 1000.0));
      then assign brightness := (if ((brightness) >= (255.0)) ? 255.0 else brightness);
    }
    out attribute io_0 : Real = brightness;
  }
  part system : Controller;
}
